/**
 * Help: how the board works, step by step, with small illustrations of the real screens.
 * The pictures are built from the board's own styles with made-up customers, so they always look
 * like the app. They are pictures only (aria-hidden, not clickable). The shop floor sees only
 * the parts that apply to it.
 */
const TICK = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 12.5l4.5 4.5L19 7.5"/></svg>';
const n = k => `<span class="hn">${k}</span>`;                        // numbered pointer
const box = done => `<span class="tick ${done ? 'done' : ''}">${done ? TICK : ''}</span>`;
const pic = (html, caption) => `<figure class="hpic"><div class="hframe" aria-hidden="true">${html}</div>${caption ? `<figcaption>${caption}</figcaption>` : ''}</figure>`;
const head = (k, title) => `<h3>${k ? `<span class="hno">${k}</span> ` : ''}${title}</h3>`;
/** Items starting with a numbered pointer explain the picture above; the rest go in a "Good to know" box. */
const steps = items => {
  const isNum = t => t.startsWith('<span class="hn">');
  const num = items.filter(isNum), tips = items.filter(t => !isNum(t));
  return (num.length ? `<ol class="hsteps">${num.map(t => `<li>${t}</li>`).join('')}</ol>` : '')
    + (tips.length ? `<div class="htips">${num.length ? '<b>Good to know</b>' : ''}<ul>${tips.map(t => `<li>${t}</li>`).join('')}</ul></div>` : '');
};

/** The whole journey of an order, left to right like the tabs. */
function flow(office) {
  const all = [
    ['Won quotes', 'Levi\'s quotes marked Ordered (and, once, Xero\'s open orders), waiting to become orders', 'M4 6h16v12H4z M4 6l8 7 8-7', 'quotes'],
    ['Sales orders', 'Checked and saved; value, dispatched, invoiced', 'M6 3h12v18H6z M9 8h6 M9 12h6 M9 16h4', 'form'],
    ['Jobs', 'The job board in running order', 'M4 5h16v14H4z M4 10h16 M9 10v9', 'jobs'],
    ['Shop floor', 'The factory ticks off each process', 'M5 12.5l4.5 4.5L19 7.5', 'floor'],
    ['Dispatch', 'Delivery note, emailed, delivered', 'M3 7h11v9H3z M14 10h4l3 3v3h-7z M7 19a1.5 1.5 0 1 0 0-.01 M17 19a1.5 1.5 0 1 0 0-.01', 'dispatch'],
    ['Xero', 'Draft invoice for Keith to approve', 'M6 3h9l3 3v15H6z M9 10h6 M9 14h6 M9 18h3', 'xero'],
  ].filter(s => office || ['floor', 'dispatch'].includes(s[3]));
  const more = [['Home', 'Start of the day: what needs attention', 'home'], ['Delivery map', 'On Dispatch: where deliveries are going, what is nearby', 'map'],
    ...(office ? [['Customers', 'In the CRM: buyers, goods in, delivery addresses', 'customers']] : [])];
  return `<div class="hjourney"><b class="hlbl">${office ? 'From quote to invoice' : 'Where your part fits'}</b>
    <div class="hflow" style="--n:${all.length}">${all.map(([t, d, path, k]) => `<a class="hstep" href="#help-${k}"><span class="ic"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${path}"/></svg></span>
      <span><b>${t}</b><small>${d}</small></span></a>`).join('')}</div>
    <div class="hmore"><b class="hlbl">Also on the board</b>${more.map(([t, d, k]) => `<a href="#help-${k}"><b>${t}</b><small>${d}</small></a>`).join('')}</div></div>`;
}

/** The whole process as a short video (made from the practice board: made-up customers only; see dev/video). */
const video = () => `<section class="hsec" id="help-video">${head(0, 'Watch: from order to invoice (about 6½ minutes, with sound)')}
    <figure class="hvideo"><video controls preload="none" playsinline poster="/help/walkthrough.jpg?v=1020d" src="/help/walkthrough.mp4?v=1020d"></video>
    <figcaption>Every step, spoken and captioned: the Xero changeover, making an order, drawings and what they need, purchase orders, pro forma, job sheet (now the front sheet), ticking orders for a total, moving a delivery date, Parts, metal prices, Jobs, the shop floor, powder coat sent out, the workshop TV, dispatch and saving notes, Xero and aged debt. Practice data only.</figcaption></figure>
  </section>`;

/** Changeover day: bring Xero's open sales orders across once, then the board is where orders are raised. */
const changeover = () => `<section class="hsec key" id="help-changeover">${head(0, 'Changeover day: moving from Xero to the board')}
    ${steps(['<span class="hn">1</span> On the <b>Xero</b> tab, press <b>Import open sales orders</b> once. Every open sales order in Xero appears on <b>Won quotes</b>.',
      '<span class="hn">2</span> On <b>Won quotes</b>, press <b>Create sales order</b> on each one. Check the lines and the customer PO, tick the processes, and save. It goes onto Jobs and the shop floor.',
      '<span class="hn">3</span> From then on, raise sales orders <b>only on the board</b>, not in Xero. The board keeps its SO numbers after the last one in Xero.',
      'Nothing is ever deleted or changed in Xero by the board. Invoices and purchase orders go to Xero as <b>drafts</b> for Keith.'])}
  </section>`;

/** Drawings, purchase orders and pro formas: everything else on an order. */
const orderExtras = () => `<section class="hsec" id="help-extras">${head(0, 'On each order: drawings, purchase orders, pro forma')}
    <p>Open an order from <b>Sales orders</b> and scroll down: each has its own section.</p>
    ${steps([
      '<b>Drawings:</b> press <b>Attach drawings</b>, or drag the PDFs from your desktop or an email onto the order\'s <b>Drawings</b> section (it outlines in blue when you can let go). Files are saved in SharePoint (Factory Jobs › Documents › Job drawings › the SO number). The shop floor gets a <b>Drawing</b> button on the job and it opens full screen. <b>Remove</b> only takes it off the job; the file stays in SharePoint.',
      '<b>Parts</b> (Sales orders › <b>Parts</b>): repeat parts and their drawings, by customer and part number. When a new order (or a repeat, or one made from Xero) has a line with a part number in the list for that customer (in its <b>Part no.</b> box; only when that box is empty does the board look for one in the description, as it does on older orders), the part\'s current drawing is attached automatically and marked <b>from Parts</b>; it is the same SharePoint file, not a copy. Add parts there with <b>Add a part</b>, or press <b>Keep for this part</b> when a drawing attached to an order shows its part number. A new revision dropped on a part becomes the current one for new orders; orders already made keep the one they had. Under the list, <b>Found on your orders</b> shows part numbers on existing orders (from the Part no. box, or spotted in the description when it is empty) that are not in Parts yet: drag the drawing onto one (or press <b>Attach drawing</b>) and the part is added with it. Whenever a part gets a drawing, it is also attached to the open orders that name it.',
      '<b>Drawings already in SharePoint:</b> when an order\'s lines have a part number (the Part no. box first, else one named in the description), the board looks in that customer\'s folders in Company Data (their client folder and their laser drawings folder) and lists the drawing under <b>Found in the customer\'s SharePoint folders</b>: the highest issue, a PDF first. Press <b>Attach</b> to put it on the order (the same file, not a copy), or open it to check first. In <b>Parts</b>, a part number found on your orders shows <b>In their SharePoint folder</b> with <b>Use it</b>, which adds the part with that drawing.',
      '<b>Material certificates:</b> when the lines name a grade (S275, S355, 304 or 316 stainless, 1050, 5083, 6082 aluminium…), the order shows a button for that grade\'s folder in Company Data › Mat Certs. A grade with no folder says so.',
      '<b>Processes from the drawing:</b> when a PDF drawing is attached (or press <b>Check processes</b> beside one), the board reads its text, such as the material, thickness, finish, holes, chamfers, flat pattern and powder coat, and says which processes the order seems to be missing, with the words it found. <b>Add</b> them or press <b>Not needed</b>. It also says when something is not one of the nine processes (bar stock, an outside thread, engraving). It cannot see bends that are only drawn, or read scanned drawings, so always check by eye. On a new order, typing a part made before ticks the processes it had then.',
      '<b>Back-to-back</b> (bought in and sent on): tick <b>Back-to-back</b> on the new sales order; once it is saved, its purchase order opens ready with the same parts and quantities, and the supplier and costs from the last PO for those parts. No processes are needed if nothing is made here. On an existing order, <b>Back-to-back PO</b> does the same.',
      '<b>Purchase orders:</b> press <b>New purchase order</b>. To repeat an earlier one, pick it under <b>Copy a previous PO</b> (POs for the same parts come first, then others for the same customer): it fills in the supplier, account and lines, and you check the quantities and costs. Otherwise choose the supplier from Xero, pick the account (materials such as steel are 5000; for consumables or subcontract work type that code, or choose <b>Not sure</b> and Keith codes it), add lines and costs (<b>Copy this order\'s parts</b> helps), then <b>Create draft PO in Xero</b>. It goes to Xero as a draft with the SO number as its reference; approve and send it from Xero, and Keith matches the supplier\'s bill to it.',
      '<b>Pro forma:</b> press <b>New pro forma</b>, choose the quantities, then <b>Make the pro forma</b> (PF-0001…). <b>Email to customer</b> makes an Outlook draft copied to Keith; the customer pays quoting the PF number. Press <b>Mark paid</b> when it arrives: the order\'s later draft invoices in Xero then say it was paid in advance. It is not a VAT invoice and never goes to Xero itself.'])}
  </section>`;

/** Home: the start of the day. */
function home(office) {
  const card = (t, d, tone) => `<div class="hcardx ${tone}"><b>${t}</b><span>${d}</span></div>`;
  return `<section class="hsec" id="help-home">${head(0, 'Home: start here each day')}
    ${office ? `<p>Mandy's Home is the day's work; Levi's is the money and what to chase. Both start with the same header: the date, how many processes were ticked off today, and the main buttons.</p>
    <p>Then, at the very top, <b>Three things today</b>: the three things most worth doing first (a customer's complaint or PO, an enquiry waiting over a day, a customer's question on a quote, an overdue task, the quote to chase, the order running latest or a repeat part to ask about), each with one sentence on why and <b>Open</b>. See <i>Three things today on Home?</i> under Questions.</p>
    <h3>Mandy's Home</h3>` : ''}
    <div class="hcardsx">
      ${office ? card('Today', '<b>New enquiries to answer</b> (opens Customers at the enquiries), <b>tasks due today</b> (with how many are overdue), <b>won quotes waiting to become orders</b> (opens Won quotes) and <b>open orders with no drawing</b> (opens the list of them below). Under the tiles: your tasks, overdue first, then today and the next 7 days, and <b>Add a task</b>.', 't-bad') : ''}
      ${office ? card('Sales this week', 'Beside Today, the same height: <b>quotes to chase</b> and <b>customers gone quiet</b> (open the CRM), <b>repeat parts to ask about</b> (opens the reorder round on the CRM) and <b>open orders with no contact saved</b> (orders for a customer with nobody in their contact book; opens Customers, where you add them).', 't-warn') : ''}
      ${card(office ? 'Two rows of cards' : 'Counts at the top', `What is late, due in the next 7 days and ready to dispatch${office ? ', and the open jobs. The second row: <b>Delivered, not invoiced</b> (notes not yet sent to Xero), <b>In Xero, not approved</b> (draft invoices the board made that nobody has approved in Xero yet; checked every 15 minutes), <b>Over 60 days</b> (customers with invoices more than 60 days old and past due in Xero, most owed first) and <b>Sent out</b> (work at other companies for powder coat or plating; 0 when nothing is out). On the Over 60 days list, <b>Draft a chase email</b> puts a polite reminder in your Outlook Drafts, to the customer\'s accounts contact, listing each invoice with a pay-online link and copied to Keith; it is never sent for you, and the list shows who chased and when. A new sales order, and its quote on Won quotes, show the same warning for that customer: you can still go ahead. Click a card to see its list' : ''}.`, 't-bad')}
      ${office ? card('Shop floor notes and the reorder round', '<b>From the shop floor</b> shows new notes the floor has left on jobs (only when there are some); <b>Got it</b> clears one. The <b>Reorder round</b> below it lists the top 5 repeat parts due again, with <b>See all</b> on the CRM.', 't-info') : ''}
      ${card('Station snapshot', 'How many jobs are waiting at each station, and how many of those are late, in one row. Tap one to open the shop floor there.', 't-info')}
      ${card('Needs attention', `What is late, at risk (due within 3 working days with processes still to do), on hold or ready to go${office ? ', plus won quotes waiting and deliveries to invoice' : ''}. Worst first, each with one button for the next step.`, 't-warn')}
      ${card('Going out', 'Switch to this to see everything due from today to the Friday of next week.', 't-ok')}</div>
    ${office ? `<h3>Levi's Home</h3>
    <p>Shorter, with the month's figures that only he sees: the month (invoiced, work in progress, break-even and target) beside <b>Sales this week</b> (quotes to chase, repeat parts to ask about, customers gone quiet, enquiries waiting) and his tasks; then four cards, the order book, running late, due in 7 days and owed over 60 days; the shop floor's notes; the reorder round; and what needs attention. Dispatch, invoicing and the station snapshot are on Mandy's Home.</p>` : ''}
  </section>`;
}

function newOrders() {
  return `<section class="hsec" id="help-quotes">${head(1, 'Won quotes')}
    <p>Levi prices the job in his quote calculator as normal. When the customer orders, he presses <b>Mark as Ordered</b> there. Within a minute the quote appears on <b>Won quotes</b>, with the one waiting longest at the top. It turns amber after 2 working days and red after 5.</p>
    ${pic(`<table class="lines inbox"><thead><tr><th>Customer</th><th>Won</th><th>Contact</th><th>Value</th><th></th></tr></thead><tbody>
      <tr><td><b>Example Fabrications Ltd</b><div class="note mono">Q-0309 · quote</div></td><td>7 Oct <span class="chip late">6 days</span></td><td>A Buyer</td><td class="num">£386.50</td>
        <td><div class="acts"><span class="btn sm pri">Create sales order</span>${n(1)}<span class="btn sm">Not a job</span>${n(2)}</div></td></tr>
      <tr><td><b>Sample Engineering Co</b><div class="note mono">Q-0312 · quote</div></td><td>14 Oct <span class="chip">1 day</span></td><td></td><td class="num">£1,240.00</td>
        <td><div class="acts"><span class="btn sm pri">Create sales order</span><span class="btn sm">Not a job</span></div></td></tr></tbody></table>`)}
    ${steps([`${n(1)} <b>Create sales order</b> opens the order form with the customer, parts, quantities and prices copied from the quote. The processes it can tell from the quote (folds, welds, inserts, paint…) are already ticked.`,
      `${n(2)} <b>Not a job</b> stops a quote being offered here, for example one already finished some other way. The quote itself is not changed, and <b>Put back</b> undoes it.`,
      'Not there yet? Press <b>Refresh</b>, and check the quote is marked Ordered in the calculator.',
      'An order that came by phone or email with no quote: <b>Sales orders › New order</b>.'])}
  </section>`;
}

function orderForm() {
  return `<section class="hsec" id="help-form">${head(2, 'Sales orders')}
    <p>The office's list of every order, like Sage's Sales Order Processing: value, customer PO, next due date, and whether it has been dispatched and invoiced. Click an order to open it. The switch above the list shows <b>Outstanding</b> (soonest due first), <b>Dispatched</b>, <b>On hold</b> or <b>Cancelled</b>; the second switch lists them <b>By SO number</b>, newest at the top, and remembers your choice; the search looks through every order.</p>
    ${pic(`<table class="lines home orders"><thead><tr><th>Customer</th><th>Ordered</th><th>Next due</th><th>Progress</th><th class="num">Net</th></tr></thead><tbody>
      <tr><td><b>Sample Engineering Co</b><span class="ref mono">SO-9790 · no PO</span></td><td>15 Oct</td><td><span class="chip soon">20 Nov</span></td><td><span class="chip">Not dispatched</span> <span class="chip">Not invoiced</span></td><td class="num">£386.50</td></tr>
      <tr><td><b>Demo Metals Ltd</b><span class="ref mono">SO-9781 · PO-1</span></td><td>14 Oct</td><td></td><td><span class="chip ok">Dispatched</span> <span class="chip ok">Invoiced</span></td><td class="num">£1,068.00</td></tr></tbody></table>`)}
    <p><b>Create sales order</b> on Won quotes, or <b>New order</b> at the top of this tab, opens the order form. It works like a Sage sales order. Check it, then press <b>Create order</b>.</p>
    ${pic(`<div class="hform">
      <div class="hrow"><label>Customer ${n(1)}<span class="f">Example Fabrications Ltd</span></label><label>Customer PO ${n(2)}<span class="f">PO-4471</span></label></div>
      <table class="lines"><thead><tr><th style="text-align:left">Part no. ${n(3)}</th><th style="text-align:left">Description</th><th>Qty</th><th>Price</th><th>Due ${n(4)}</th></tr></thead><tbody>
        <tr><td style="text-align:left" class="mono">BRK-1001</td><td style="text-align:left">Bracket, 3mm S275</td><td>50</td><td>£12.40</td><td>23 Oct</td></tr>
        <tr><td style="text-align:left" class="mono">BRK-1001</td><td style="text-align:left">Bracket, 3mm S275</td><td>50</td><td>£12.40</td><td>30 Oct</td></tr></tbody></table>
      <div class="hrow"><span class="btn sm">Split into call-offs</span>${n(5)}<span style="flex:1"></span><span class="btn sm pri">Create order</span></div>
      <table class="lines"><thead><tr><th style="text-align:left">Processes ${n(6)}</th>${['Laser', 'Fold', 'Weld', 'P/Coat'].map(p => `<th style="text-align:center">${p}</th>`).join('')}</tr></thead><tbody>
        ${[['<b>All lines</b>', [1, 1, 0, 0]], ['<span class="mono">BRK-1001</span> Bracket, 3mm S275', [1, 1, 0, 0]], ['<span class="mono">BRK-1001</span> Bracket, 3mm S275', [1, 1, 0, 0]]]
          .map(([t, on]) => `<tr><td style="text-align:left">${t}</td>${on.map(x => `<td style="text-align:center"><span class="hcheck">${box(!!x)}</span></td>`).join('')}</tr>`).join('')}</tbody></table></div>`)}
    ${steps([`${n(1)} The customer list comes from Xero, and picking one fills in the contact, email and delivery address.`,
      `${n(2)} Type the customer's order number. It goes on every document and on the invoice.`,
      `${n(3)} Each line has two boxes, as in Xero and Sage: <b>Part no.</b> for the customer's part number (optional: leave it empty when there is none) and <b>Description</b> (needed on every line). The part number is what Parts and the drawings matching look at first, so a part's drawing finds its way onto the order by itself. It goes on the documents and in front of the description on the Xero invoice.`,
      '<b>Picking a part:</b> start typing in either box and pick from the list: this customer\'s parts from earlier orders first (with the last price charged), then other customers\' parts, then Parts and Xero\'s Products and services. Picking one fills in both boxes (Xero\'s item code and the Parts part number go in Part no.) and the price; change them if needed, or just type a new part. Lines from a quote fill only the description, as the quote calculator has no part number.',
      `${n(4)} Each line has its own due date. Two lines of the same part with different dates are two deliveries.`,
      `${n(5)} <b>Split into call-offs</b> turns one line into several deliveries. See <a href="#help-calloffs">Call-offs</a> below.`,
      `${n(6)} Tick the processes <b>each part</b> needs, in the <b>Processes</b> table under the lines: a row per line, a box per process (Levi, 22 Oct: each part may need a different process). With more than one line, the <b>All lines</b> row at the top ticks or unticks that process on every line in one click. A new line starts with the ticks of the line above. Only the processes ticked on some line appear on the shop floor, and each station's tablet lists only the parts that need it.`,
      'After saving, the <b>order acknowledgement</b> opens. Press <b>Email to customer</b> to put it in your Outlook Drafts with the PDF attached.'])}
  </section>`;
}

/** Call-offs: one order, delivered in parts on set dates (Sage: one order line per delivery). */
function calloffs() {
  const line = (qty, due, extra = '') => `<tr><td style="text-align:left">Bracket, 3mm S275</td><td>${qty}</td><td>£12.40</td><td>${due}</td>${extra}</tr>`;
  return `<section class="hsec key" id="help-calloffs">${head(3, 'Call-offs')}
    <p>A call-off is one order delivered in parts on set dates, for example 200 brackets, 50 a week for four weeks. As in Sage, each delivery is its own <b>line on the order with its own due date</b>. Everything else follows from that: the board, the shop floor, the dispatch notes and the invoices all work one delivery at a time.</p>

    <h4>Setting one up</h4>
    ${pic(`<div class="hform">
      <table class="lines"><thead><tr><th style="text-align:left">Part</th><th>Qty</th><th>Price</th><th>Due</th></tr></thead><tbody>${line('<b>200</b> ' + n(1), '23 Oct')}</tbody></table>
      <div class="panel"><div class="hrow"><span class="btn sm">Split into call-offs…</span>${n(2)}</div>
        <div class="hrow"><label>Deliveries<span class="f">4</span></label><label>How often<span class="f">Weekly ▾</span></label><label>First delivery<span class="f">23/10/2026</span></label>${n(3)}</div>
        <div class="hrow"><span class="btn sm">Split the lines</span>${n(4)}</div></div></div>`, 'Before: one line for the whole quantity.')}
    ${pic(`<table class="lines"><thead><tr><th style="text-align:left">Part</th><th>Qty</th><th>Price</th><th>Due ${n(5)}</th></tr></thead><tbody>
      ${line(50, '23 Oct')}${line(50, '30 Oct')}${line(50, '6 Nov')}${line(50, '13 Nov')}</tbody></table>`, 'After: one line per delivery. The order total is unchanged.')}
    ${steps([`${n(1)} On the order form, enter the part with the <b>full quantity</b> and the price, as one line.`,
      `${n(2)} Press <b>Split into call-offs…</b> under the lines.`,
      `${n(3)} Say how many <b>deliveries</b>, <b>how often</b> (weekly, every 2 weeks or monthly) and the date of the <b>first delivery</b>.`,
      `${n(4)} Press <b>Split the lines</b>. Every line on the order is shared out across the deliveries. If it does not divide exactly, the first deliveries take the extra (201 in 4 = 51, 50, 50, 50).`,
      `${n(5)} Check the lines. You can change any quantity or date before saving, just like in Sage, then press <b>Create order</b>.`,
      '<b>An uneven schedule</b> (say 80 now, 60 in a fortnight, the rest when called for): skip the split and use <b>Add a line</b> instead, typing each delivery\'s quantity and date yourself.'])}

    <h4>While it runs</h4>
    ${pic(`<table class="jobs"><thead><tr><th>Customer</th><th>Sales order</th><th>Due</th></tr></thead><tbody>
      <tr><td class="cust"><b>Example Fabrications Ltd</b><div class="meta"><span class="chip">Delivery 2 of 4</span> ${n(6)}</div></td><td class="so">SO-9786</td><td><span class="chip soon">30 Oct</span></td></tr></tbody></table>
      <div class="panel" style="margin-top:10px"><table class="lines"><thead><tr><th style="text-align:left">Part</th><th>Due</th><th>Ordered</th><th>Outstanding</th><th>This dispatch</th></tr></thead><tbody>
        <tr><td style="text-align:left">Bracket, 3mm S275</td><td>30 Oct</td><td>50</td><td>50</td><td><span class="f">50</span> ${n(7)}</td></tr>
        <tr><td style="text-align:left">Bracket, 3mm S275</td><td>6 Nov</td><td>50</td><td>50</td><td><span class="f">0</span></td></tr>
        <tr><td style="text-align:left">Bracket, 3mm S275</td><td>13 Nov</td><td>50</td><td>50</td><td><span class="f">0</span></td></tr></tbody></table></div>`)}
    ${steps([`${n(6)} The job board and shop floor show which delivery is next (<b>Delivery 2 of 4</b>) and its due date. The shop floor shows how many are needed for the next delivery.`,
      `${n(7)} On <b>Dispatch</b>, the quantities are already filled in for <b>the next delivery only</b>; later deliveries stay at 0 until their turn. Change them if the customer wants more now.`,
      'Each delivery gets its own <b>dispatch note</b>, which lists what is still to come on the order, and its own <b>draft invoice</b> in Xero once delivered. So the customer is invoiced per call-off, for exactly what went.',
      'The order stays on the board until the last delivery has gone, then moves to <b>Finished</b>.'])}

    <h4>When the customer changes a call-off</h4>
    ${steps(['Open the order on <b>Sales orders</b> and press <b>Amend order</b>.',
      '<b>Earlier or later:</b> on <b>Jobs</b>, click the due date and pick the new one (with more than one delivery, that moves the next one), or Amend the line\'s due date on Sales orders. If it is now urgent, bring the job forward on <b>Jobs</b> with ⤒.',
      '<b>More or fewer:</b> change that line\'s quantity. It can\'t go below what has already been dispatched on it.',
      '<b>An extra delivery:</b> press <b>Add a line</b> with the part, quantity, price and date.',
      '<b>A delivery no longer wanted:</b> delete its line (only possible while nothing has been sent on it).',
      '<b>A new PO for each call-off:</b> when the customer\'s call-off PO arrives, press <b>Amend</b> and type it in that line\'s <b>Call-off PO</b> box. Leave the box blank to use the order\'s own PO. The delivery note, its email and the Xero invoice for that delivery then quote the call-off PO.'])}
  </section>`;
}

function jobsBoard() {
  const pt = (name, done) => `<span class="pt ${done ? 'done' : ''}"><span class="bx">${done ? TICK : ''}</span>${name}</span>`;
  const row = (o, mv, cust, ref, due, pills, ready) => `<tr class="${ready ? 'ready' : ''}"><td class="ord"><span class="n ${mv ? 'placed' : ''}">${o}</span><span class="mv"><span class="btn sm">⤒</span><span class="btn sm">▲</span><span class="btn sm">▼</span></span></td>
    <td><b>${cust}</b><span class="ref mono">${ref}</span>${ready ? '<div class="chips"><span class="chip ok">Ready to dispatch</span></div>' : ''}</td><td>${due}</td><td>${pills}</td></tr>`;
  return `<section class="hsec" id="help-jobs">${head(4, 'Jobs')}
    <p>Every open order, one row each. <b>Not started</b> has nothing ticked or sent, <b>In progress</b> has something ticked or sent, <b>Finished</b> is all dispatched.</p>
    ${pic(`<table class="lines home board"><thead><tr><th>Order ${n(1)}</th><th>Customer</th><th>Due</th><th>Processes ${n(2)}</th></tr></thead><tbody>
      ${row(1, true, 'Sample Engineering Co', 'SO-9790 · PO-114', '<span class="chip soon">20 Nov</span>', pt('Laser') + pt('Weld') + pt('P/Coat'))}
      ${row(2, false, 'Example Fabrications Ltd', 'SO-9786 · no PO', '<span class="chip late">17 Oct</span>', pt('Laser', true) + pt('Fold', true) + pt('P/Coat', true), true)}
      ${row(3, false, 'Demo Metals Ltd', 'SO-9788 · PO-92', '<span class="chip">29 Oct</span>', pt('Laser', true) + pt('Fold'))}</tbody></table>`)}
    ${steps([`${n(1)} <b>Moving jobs</b> (Levi and Mandy). <b>All open</b> lists every job not yet sent, soonest due first; jobs moved by hand stay where they were put, the rest follow in date order underneath.
        <ul><li><b>Drag</b> a job by ⠿ at the left of its row; a green line shows where it will land.</li>
        <li><b>⤒</b> puts it at the top, <b>▲ ▼</b> move it one place.</li>
        <li><b>Change the due date:</b> click the date and pick a new one; the job moves to its place in date order.</li>
        <li><b>Biggest first:</b> click the <b>Outstanding</b> heading to list jobs by value, then ⤒ to bring a big one to the top (handy for the month's target); click the heading again to go back.</li>
        <li>Every move has <b>Undo</b> on the message for a few seconds. <b>Put everything back in date order</b> (under the table) clears all the hand moves.</li>
        <li>Moving is off while there is something in the search box: clear it and the handles come back.</li></ul>
        The shop floor follows this order straight away.`,
      `<b>This month</b> (Levi only) is one line above the Jobs list (invoiced, work in progress, the gap, and how much more is due later to bring forward); the full panel is on Home, which shows three figures and an upright steel tube from £0 at the bottom to the ideal target at the top, beside the figures: <b>Invoiced</b> so far this month (the solid fill: amber until break-even, green past it), <b>Work in progress</b> (blue: open orders due by the month end) and the <b>Gap to target</b> (the empty steel left after both). Invoiced counts work dispatched on the board and sales invoices approved in Xero that the board did not raise (the weeks before changeover, or one typed straight into Xero), less credit notes; the small line beside the tube says how much came from each. The ring marks break-even and the small blue arrow (pace) is where an even pace would be by today. If there is a gap, it says how much more is on order but due later, which could be brought forward. <b>Set break-even and target</b> (on Home) types both figures in once; they apply to every month.`,
      `${n(2)} <b>Tick a process</b> by clicking its pill when that step is finished. Click it again to undo.`,
      'A green row means every process is ticked: the job is ready to dispatch.',
      '<b>Front sheet</b> (open the job, or from the order acknowledgement): the printed sales order front sheet for the job folder with the drawing, set out like Xero\'s. At the top: the customer and delivery address, the order number and date, customer PO, our quote and the <b>Required</b> date in bold. Then a row per part: quantity, part number, description and a column for each process on the order, with a box to tick where that part needs the process (an empty space where it does not). Under it, a <b>Certificate batch no.</b> box to write in. No prices. Before printing, <b>What is this sheet for?</b> lets you set <b>To make</b> for each line, for example just this week\'s call-off. It starts on the next delivery; <b>Everything outstanding</b> fills in the rest. This only changes the sheet, never the order. The board is still the live record, so tick processes there too.',
      'Click a row to open the whole order. From there: <b>Amend</b>, <b>Hold</b> / <b>Release</b>, <b>Cancel</b>, <b>Repeat order</b>, <b>Order acknowledgement</b> and <b>Dispatch…</b>.',
      'Prices and values are on <b>Sales orders</b>; the shop floor never sees them.',
      '<b>Adding orders up:</b> on <b>Sales orders</b>, tick the box at the start of each order (Shift-click to tick a run of them, or the box in the heading for every order shown). A panel in the corner keeps a running total: how many, their order value, and what is still to dispatch. <b>Clear</b> unticks them all.'])}
  </section>`;
}

function shopFloor(office) {
  const step = (p, done, here) => `<span class="step${done ? ' done' : ''}${here ? ' here' : ''}"><span class="bx">${done ? TICK : ''}</span><span><b>${p}</b><small>${done ? 'Done 09:42' : here ? 'Tap when done' : 'To do'}</small></span></span>`;
  return `<section class="hsec" id="help-floor">${head(office && 5, 'Shop floor')}
    <p>${office ? 'The screen the factory uses on the touch screen. ' : ''}Jobs are listed in the order the office wants them done: anything brought forward first, then soonest due.</p>
    ${pic(`<div class="kiosk"><div class="tiles">
        <span class="tile hot"><span class="nm">Laser ${n(1)}</span><span><span class="ct"><b>3</b>jobs waiting</span><span class="tag late">1 late</span></span></span>
        <span class="tile"><span class="nm">Fold</span><span><span class="ct"><b>2</b>jobs waiting</span><span class="tag ok">On time</span></span></span>
        <span class="tile idle"><span class="nm">Weld</span><span><span class="ct"><b>0</b>jobs waiting</span><span class="tag">Nothing waiting</span></span></span></div>
      <div class="fcard late"><div class="ftop"><span class="pos">1</span><div><div class="cu">Example Fabrications Ltd<span class="so">SO-9786</span></div><div class="parts"><span><b>50</b> × Bracket, 3mm S275</span></div></div>
        <div class="side"><span class="tag late">2 days late</span></div></div>
        <div class="route">${step('Laser', true)}<span class="arrow">→</span>${step('Fold', false, true)} ${n(2)}<span class="arrow">→</span>${step('P/Coat')}</div>
        <p class="fstat">1 of 3 done · next: <b>Fold</b></p></div></div>`)}
    ${steps([`${n(1)} The screen starts on the <b>station tiles</b>. Tap your station to see only the jobs waiting for it, in the order to do them. Each job shows only your step to tap and only the parts that need it, with where they go next underneath (<b>Then: Weld → P/Coat</b>, or <b>Last step: back to the office</b>). If a step before yours is still to do, an amber line says so (<b>Before this: Laser still to do</b>). <b>All jobs</b> shows everything: every part and the whole route.`,
      '<b>Changing the order at one station</b> (Levi and Mandy, signed in on their own computer): open the station, then ⤒ (to the top), ▲ ▼ (one place) on a job. Only that station changes; the other stations and Jobs keep the running order. <b>Back to the running order</b> (top of the station) clears the moves there. Every move has <b>Undo</b>. The workshop screen just follows the order, without the buttons.',
      `${n(2)} Each job shows its whole route. When your process is finished, <b>tap its step</b>. It turns green with the time, and the message at the bottom says what comes next.`,
      'Tapped the wrong one? Tap the green step again, or press <b>Undo</b> on the message.',
      'When every step is green the job is <b>ready to dispatch</b> and goes back to the office. The Dispatch tab shows it too.',
      'A job <b>on hold</b> can\'t be ticked: the office has paused it, so don\'t start it.',
      '<span class="chip late">Brought forward</span> means the office has moved this job up. Do it first.',
      'Tap <b>Drawing</b> on a job to see its drawing full screen; <b>Close</b> goes back. <b>Job details</b> shows the full job.',
      'The shop floor login (workshop@) only has this screen and the TV board: no other tabs and no prices. The prices are locked away from that login in the database itself, not just hidden on screen.',
      'After <b>2 minutes</b> untouched the screen goes back to the tiles. <b>Kiosk mode</b> (under the tiles) is for the shared screen: it goes full screen where the browser allows it, hides the header and tabs so the screen stays on the Shop floor, and is remembered on that screen. <b>Leave kiosk mode</b> brings them back.'])}
  </section>`;
}

function dispatch(office) {
  const seg = on => `<div class="seg">${[['Ready', 2], ['Out for delivery', 1], ...(office ? [['Waiting for Xero', 1]] : []), ['All notes', 6]]
    .map(([t, k]) => `<button type="button" aria-pressed="${t === on}">${t} <em>${k}</em></button>`).join('')}</div>`;
  return `<section class="hsec" id="help-dispatch">${head(office && 6, 'Dispatch')}
    <p>The <b>Dispatch</b> tab shows <span class="badge go">2 ready</span> when jobs are finished. The cards count what is ready, not emailed, out for delivery and${office ? ' waiting for Xero' : ' sent this week'}. The switch shows <b>Ready</b>, <b>Out for delivery</b>, ${office ? '<b>Waiting for Xero</b> and ' : 'and '}<b>All notes</b>; it opens on the first with something in it.</p>
    ${pic(`<div class="hrow">${seg('Ready')}</div>
      <table class="lines home dispatch"><thead><tr><th>Customer</th><th>Due</th><th>To send</th><th class="act">Next step</th></tr></thead><tbody>
      <tr><td><b>Demo Metals Ltd</b><span class="ref mono">SO-9781 · PO-1</span></td><td><span class="chip soon">24 Oct</span></td><td><b>12</b> × Cabinet</td><td class="act"><span class="btn sm pri">Dispatch</span>${n(1)}</td></tr></tbody></table>
      <div class="hrow" style="margin-top:14px">${seg('Out for delivery')}</div>
      <table class="lines home dispatch"><thead><tr><th>Note</th><th>Customer</th><th>Emailed</th><th class="act">Next step</th></tr></thead><tbody>
      <tr><td class="mono">DN-0007</td><td><b>Demo Metals Ltd</b><span class="ref mono">SO-9781 · PO-1</span></td><td><span class="chip soon">Not emailed</span></td>
        <td class="act"><div class="next"><span class="btn sm pri">Email note…</span>${n(2)} <form class="inv"><input type="text" placeholder="Signed by (optional)"><span class="btn sm">Mark delivered</span></form>${n(3)}</div></td></tr></tbody></table>`)}
    ${steps([`${n(1)} <b>Dispatch</b> opens the delivery note with everything due filled in. It opens above the list; <b>Close</b> puts it away. Change a quantity to send part of it: the rest stays outstanding, as in Sage. Press <b>Create dispatch note</b>, then print it to go with the goods. To send part of a job that isn't finished, choose it under the Ready list.`,
      `${n(2)} <b>Email note…</b> opens the delivery note. <b>Email to customer</b> puts it in Outlook Drafts with the PDF.`,
      `${n(3)} When the goods have arrived, the driver marks it delivered on the phone and the customer signs on the screen (<b>Driver's screen</b>, top right; see <a href="#help-faq">Marking a delivery on the phone</a> under Questions). From the office: type who signed for them (if known) and press <b>Mark delivered</b>.${office ? ' Only delivered notes can be invoiced.' : ''}`,
      `A note signed for on the phone prints and emails with a filled-in <b>Received by</b> box: the name (or where it was left), the signature, the date and time, and who delivered it. ${office ? 'Open it from <b>All notes</b> or <b>Waiting for Xero</b> and press <b>Email to customer</b> to send it as proof of delivery.' : ''}`,
      ...(office ? ['<b>Made a note by mistake, or the goods came back?</b> On <b>All notes</b> press <b>Cancel</b> beside it, then <b>Yes</b>. It stays on the list crossed out (its number is never reused) and the quantities go back to outstanding. A note already invoiced in Xero can only be credited in Xero.'] : [])])}
  </section>`;
}

function xero() {
  return `<section class="hsec" id="help-xero">${head(7, 'Invoicing in Xero')}
    <p>Every delivered note waits under <b>Dispatch › Waiting for Xero</b>.</p>
    ${pic(`<div class="hrow"><div class="seg">${[['Ready', 2], ['Out for delivery', 1], ['Waiting for Xero', 1], ['All notes', 6]].map(([t, k]) => `<button type="button" aria-pressed="${t === 'Waiting for Xero'}">${t} <em>${k}</em></button>`).join('')}</div><span class="btn pri">Create 1 draft invoice in Xero</span>${n(2)}</div>
      <table class="lines home xero"><thead><tr><th></th><th>Note</th><th>Customer</th><th>Xero contact</th><th class="num">Net</th></tr></thead><tbody>
      <tr><td>${box(true)}</td><td class="mono">DN-0007</td><td>Demo Metals Ltd</td><td>Demo Metals Limited ${n(1)}</td><td class="num">£1,068.00</td></tr></tbody></table>`)}
    ${steps([`${n(1)} The board matches each customer to their Xero contact. If it cannot be sure, pick the contact once and it is remembered.`,
      `${n(2)} <b>Create draft invoices</b> makes one <b>draft</b> invoice per delivery note in Xero, for exactly what was sent, with the SO, PO and DN numbers on it.`,
      'Keith checks and approves them in Xero as usual. The board never approves, sends or deletes anything in Xero.',
      '<b>Changeover day:</b> on the Xero tab, press <b>Import open sales orders</b> once. It brings Xero\'s open sales orders onto Won quotes. After that, orders are only raised on the board.'])}
  </section>`;
}

function mapAndCustomers(office) {
  return `<section class="hsec" id="help-map">${head(0, 'Map')}
    <p>Where the open orders are going, one pin per postcode, so Levi can see when a second delivery fits the same run. Open it with <b>Delivery map</b> at the top of <b>Dispatch</b>.</p>
    ${pic(`<div class="hfilters">${[['Running late', '#B4321F', 1, true], ['Out for delivery', '#2557A7', 1, true], ['Ready to dispatch', '#25744A', 2, true], ['Due in the next 7 days', '#B45309', 3, true], ['Later', '#64646A', 6, false]]
        .map(([t, c, k, on]) => `<span class="hpill ${on ? 'on' : ''}" style="--k:${c}"><span class="hbox">${on ? '✓' : ''}</span>${t} <small>${k}</small></span>`).join('')} ${n(1)}</div>
      <div class="hmap"><span class="hpin" style="--k:#B4321F;left:58%;top:22%"></span><span class="hpin" style="--k:#2557A7;left:44%;top:70%"></span><span class="hpin" style="--k:#25744A;left:52%;top:52%"></span><span class="hpin" style="--k:#B45309;left:30%;top:40%"></span>
        <div class="hpop">${n(2)} <b>SO14 3TJ</b><br>SO-9781 · out for delivery<br><small><b>Within 10 miles:</b> SO-9782 (6.1 mi), SO-9783 (6.4 mi)</small></div></div>`)}
    ${steps([`${n(1)} The coloured boxes along the top switch each kind of job on or off. Filled in with a tick = shown on the map; outline only = hidden. The number is how many jobs of that kind there are. <b>Later</b> (grey) is off to start with.`,
      `${n(2)} Click a pin (the number is how many jobs are there) to see the jobs at that address and <b>what else is within 10 miles</b> (change it to 5, 15 or 25 next to the boxes). Click an order number to open it.`,
      '<b>Stops</b>, beside the map (under it on a phone), lists every address, most urgent first, with how many other stops are nearby. Click one to zoom to it; the dashed ring shows the nearby distance. <b>Show all</b> zooms back out.',
      'A pin takes the colour of the most urgent job at that address, so check the list in its popup: a delivery and a late job at the same customer share one pin.',
      'The postcode comes from the order\'s delivery address, else the customer\'s usual delivery address in Customers' + (office ? ', else their address in Xero' : '') + '. Orders with no postcode are listed under the map in <b>Not on the map</b>; give them an address and they appear.',
      'The van\'s live position is not shown yet; it can be added later if the van gets a tracker or the driver shares his phone\'s location.'])}
  </section>
  ${office ? `<section class="hsec" id="help-customers">${head(0, 'Customers (contact book)')}
    <p>Xero's contacts are often the customer's accounts people. <b>Customers</b> (in the <b>CRM</b> tab) keeps the people operations actually deal with, and where goods go. Xero is not changed.</p>
    ${steps(['Pick a customer on the left (or type one under the list and press <b>Open</b>).',
      '<b>Add a person</b> with a role: Orders / buyer, Goods in / deliveries, Accounts or Other. Tick <b>Main contact</b> for the one to use first.',
      '<b>Add a delivery address</b>, with the postcode, and tick <b>Usual delivery address</b> for the normal one. <b>Copy in Xero\'s address</b> fills the form from Xero (their delivery address if Xero has one, else their main address) for you to check and save. <b>Copy in Xero\'s contact</b> does the same for a person.',
      'New orders then fill in the <b>main Orders / buyer</b> contact and the <b>usual address</b> instead of Xero\'s. Other saved addresses are in <b>Saved delivery addresses</b> on the order form, and saved people appear when you click in <b>Contact</b>.',
      'Delivery notes are emailed to the <b>main Goods in / deliveries</b> contact when there is one, otherwise to the order\'s contact.',
      'On the order form, <b>Save contact and address to the contact book</b> keeps what you typed for next time.'])}
  </section>` : ''}`;
}

function emails(office) {
  return `<section class="hsec" id="help-email">${head(0, 'Emails')}
    ${pic(`<div class="hmail"><div class="hmail-h"><b>Drafts</b> · Outlook</div><div class="hmail-r"><b>Demo Metals Ltd</b><span>Delivery note DN-0007 for order SO-9781</span><span class="chip">PDF</span></div></div>`)}
    ${steps(['The board never sends an email itself. <b>Email to customer</b> puts a ready-made email, with the PDF attached, in <b>your own Outlook Drafts</b> and opens it.',
      'Check it, then press <b>Send</b> in Outlook. If you do not send it, nothing reaches the customer.',
      office ? 'The first time you email, Microsoft may ask you to sign in again. That happens once.' : ''].filter(Boolean))}
  </section>`;
}

function faq(office) {
  const q = [
    ['How do I see the drawing?', 'Press Drawing on the job (or open Job details and pick it under Drawings). It opens full screen; press Close to go back.'],
    ['I ticked the wrong box.', 'Tap it again, or press Undo on the message at the bottom of the screen.'],
    ['How do I go back?', 'Press ← Back (top left, or at the top of an open order), or your browser\'s Back button. Each press steps back one screen: closing an order, then a list opened from a card, then the tab before.'],
    ['I did something by mistake.', 'Most things show a message at the bottom with Undo for a few seconds: ticking a process, moving a job, changing a due date, making a dispatch note, marking delivered, hold, release and cancel. Things that cannot be undone ask Are you sure first.'],
    ['The screen looks out of date.', 'It updates by itself when anyone makes a change. If in doubt, refresh the page.'],
    ['How do I print a front sheet?', 'Open the job (tap its sales order number) and press <b>Front sheet</b>. It is set out like Xero\'s sales order front sheet: a row per part with a tick box for each process that part needs, the Required date in bold and a Certificate batch no. box to write in. Check the To make quantities (they start on the next delivery and can be changed for this sheet only), then press Print.'],
    ['It says I am not on the staff list.', 'Ask Gecko IT to add your Microsoft 365 address.'],
    ['Marking a delivery on the phone (the driver\'s screen)?', 'On the phone, open <b>jobs.clarke-lane.co.uk/#deliveries</b> and sign in with your Clarke Lane Microsoft account. '
      + 'Then put it on the home screen so it opens like an app: on an iPhone press <b>Share</b> › <b>Add to Home Screen</b>; on Android press the menu (⋮) › <b>Add to Home screen</b> or <b>Install app</b>. '
      + 'The first time you open it from the home screen, sign in once more (the phone keeps the app separate from the browser). It opens on Home (the office) or the Shop floor: press <b>Deliveries</b> (on Dispatch it is <b>Driver\'s screen</b>). '
      + 'Every note out for delivery is a big card. Tap the one you are at: the address, <b>Navigate</b> (opens Maps with directions), <b>Call</b> when the contact book has a number, the parts and their PO. '
      + 'Under <b>Delivered</b>, type who is signing and hand them the phone to sign in the box with a finger (<b>Clear</b> to start again). If nobody can sign, tick <b>Nobody to sign</b> and say where it was left. Press <b>Save delivery</b>. '
      + 'Straight away the office sees it under <b>Dispatch › Waiting for Xero</b>, ready to invoice, and the delivery note shows who signed, the signature and the time, so Mandy can open it and press <b>Email to customer</b> as proof of delivery. Saved by mistake? Press Undo on the message, or undo on Dispatch › All notes. No prices are shown on this screen.'],
  ];
  if (office) q.push(
    ['A quote I marked Ordered is not on Won quotes.', 'Press Refresh. If it is still missing, check the quote says Ordered in the calculator.'],
    ['I made an order by mistake.', 'Open it and press Delete (made by mistake). That only works while nothing has been dispatched; after that, use Cancel.'],
    ['A dispatch note was made by mistake, or the goods came back.', 'On the Dispatch tab, under All notes, press Cancel beside the note, then Yes. The note stays on the list marked cancelled, and its quantities go back to outstanding on the order. Once a note is invoiced in Xero it can only be credited in Xero.'],
    ['The customer wants to change the order.', 'Open it and press Amend order: change quantities, prices or dates, or add lines. Lines already dispatched cannot go below what was sent.'],
    ['The delivery date has moved?', 'Open the order, press <b>Amend order</b> and change <b>Promised delivery</b>: every line still on the old date (and not yet dispatched) moves with it, so Next due changes too. Lines on other dates (call-offs) keep theirs; change those in each line\'s Due box. Then press <b>Save the changes</b>. On Jobs you can also click a due date to change it.'],
    ['Hold an order?', 'Open it and press Hold. A held order cannot be dispatched until you press Release.'],
    ['A customer\'s page: orders, invoices, emails, tasks?', '<b>CRM › Customers</b>, pick a customer. <b>Overview</b>: how often they order, when they last did, what they buy most, open orders and quotes, unpaid invoices, anything worth a call (a repeat part due, work they have never had from us), their tasks and the latest. You can have AI write a short summary with one next step; only Levi sees their spend. <b>Orders and invoices</b>: the board\'s orders and their Xero invoices (paid, owed or overdue). <b>Quotes</b>: from the quote calculator. <b>Emails</b>: found live in your mailbox, your colleague\'s and info@ by their email domain (nothing is copied); <b>Make a task</b> from any of them. <b>Tasks and notes</b>: note a call, visit or anything worth remembering, and add tasks. <b>Contacts</b>: people and delivery addresses, as before.'],
    ['Preparing an enquiry for quoting (the quote pack)?', 'Open an enquiry (<b>CRM › Customers</b>, the enquiries list) and press <b>Prepare for quoting</b>. AI reads the email and its attached PDFs and pictures (up to 4, 12 MB in all; DXF and STEP files cannot be read) and lists each part with what the drawing says (part number and revision, material, thickness, quantity, finish and the processes it needs), then <b>Questions to ask</b> before you can price it and anything to <b>Watch out</b> for (tight tolerances, materials we do not stock, unusual finishes, short lead times). It never guesses a size or a quantity: anything unclear becomes a question. <b>Copy for the quote calculator</b> copies it as plain text, one line per part, then the questions. <b>Ask these questions</b> drafts a reply with AI that asks exactly those questions (you check it and it goes in your Outlook Drafts). <b>Read again</b> if more drawings come in. Enquiries with a pack show a <b>quote pack</b> chip. About 10p each. No prices are sent, and always check it against the drawings before you price.'],
    ['Three things today on Home?', 'At the top of Levi\'s and Mandy\'s Home: the three things most worth doing first today, from what the board already knows. In order: a customer\'s complaint, a customer\'s PO, an enquiry that has waited over a day for a reply (the oldest), a customer\'s question on a quote, one of your overdue tasks, the quote most worth chasing (its follow-up is due, or it is the most likely to win), the order running latest and the repeat part most worth asking about; one of each where it can. AI adds one sentence on why each matters today, and <b>Open</b> takes you to it. It is worked out when you first open the board each day (it waits up to 8 seconds for Xero and the quote calculator) and kept for the day; <b>Refresh</b> picks again from what the board knows now; <b>Not today</b> hides it until tomorrow. Levi\'s may mention what a quote or a late order is worth; Mandy\'s never mentions money. If the AI cannot be reached the three still show with a plain line each. Under 1p a day.'],
    ['Tasks and follow-ups?', 'Press <b>Add a task</b> on Home, a customer page, an enquiry or an email: what needs doing, the customer, when, and who it is for. Tasks show on Home for that person (in <b>Today</b> on Mandy\'s, under <b>Sales this week</b> on Levi\'s; overdue in red); tick one when it is done (Undo if not).'],
    ['Website enquiries to info@?', 'The board reads new emails to info@ while it is open (every 15 minutes, or <b>Check now</b>), and AI sorts each into a new enquiry, an existing customer writing about an order or quote, or neither, picking out who it is from, their phone number, what they want and whether drawings are attached. A known customer (by their email address, their company\'s email domain or the company name) writing about an order or quote that already exists is filed as a customer\'s email, not a new enquiry, so it does not count as an enquiry waiting. <b>Enquiries</b> (on Customers, and Levi\'s CRM) lists new ones first with how long each has waited: a quick first reply wins more work. Open one to <b>Draft a reply with AI</b> (edit it, then it goes in your Outlook Drafts), <b>Add a task</b>, <b>Add as a customer</b>, and mark it Replied, Quoted, Won, Lost or Not an enquiry. Customers\' emails about their orders are listed below the enquiries with a button for each (see <i>Customers\' emails about orders and quotes?</i>). The emails stay in Outlook; only what the AI read from them is kept. Needs a one-off Microsoft 365 permission and access to the mailbox.'],
    ['CRM: following up quotes and customers?', 'The <b>CRM</b> tab (it was called Sales; Levi and Mandy) has three parts: <b>Follow-ups</b>, <b>Customers</b> (every customer\'s page, with their contacts, orders, quotes, emails, tasks and SharePoint files) and <b>Ideas</b>. Follow-ups reads every quote in your quote calculator. <b>This month</b> (Levi only) shows orders booked so far against your monthly target (set on Home), the gap, what your open quotes are likely to bring in, and roughly how many more quotes that gap means at your own win rate. <b>Chase these today</b> lists the quotes most worth a follow-up: <b>Draft follow-up email</b> puts a short chaser in your Outlook Drafts and books the next follow-up for a week later; <b>Log a call</b> notes it; <b>Follow up on</b> picks the day; <b>Lost</b> takes a reason (Undo if it was a mistake). <b>Open quotes</b> has every live quote by stage; old ones nobody ordered are under Likely dead. <b>Customers to get back in touch with</b> uses Xero\'s invoices to find regular customers who have gone quiet and ones who have stopped: <b>Write an email</b> has AI write a short, personal email from what they buy and when (and anything you add, such as spare capacity), which you edit and put in your Outlook Drafts. <b>Reorder round</b> lists repeat parts past their usual gap, with <b>Write an email</b>, <b>Asked</b> and <b>Not needed</b> (see <i>The reorder round</i> below); <b>Could give us more</b> lists regular customers who have never had finishing, folding or welding from us, with <b>Write an email</b>. <b>Email your customers</b>: type what is new (capacity, a new machine, new colours), tick customers, and AI drafts a personal email for each in your Outlook Drafts. <b>What your quotes say</b> is your win rate and how quickly won quotes come in. Each open quote\'s <b>Chance</b> comes from your own win rate, the customer\'s and how old the quote is. The quote calculator does not record the day a quote was ordered, so until it does the board uses a general curve for how quickly quotes come in (it says so there); add an <b>Ordered Date</b> column to the Quotes list in SharePoint, filled in when a quote is ordered, and it will use your own. Nothing is ever sent for you, and your quote calculator is not changed.'],
    ['The reorder round (repeat parts due again)?', 'Some customers order the same part again and again. From Xero\'s invoices the board knows how often (say every 3 weeks) and spots when one is past its usual time. Once a week, ideally Monday morning, go down the <b>Reorder round</b> (on Home, the top 5; on <b>CRM › Follow-ups</b>, all of them) and ask each customer if they need the next batch. <b>Write an email</b> has AI write a short note about that part; once you put it in your Outlook Drafts the board notes it as asked. Rang them instead? Press <b>Asked</b>. They do not need it for now? <b>Not needed</b> hides it for 90 days. Asked ones come back after 30 days if nothing happens. When an order for that part comes in after you asked, it shows under <b>Came back in</b>, and the header counts this month\'s asks and wins (Levi also sees what the wins are worth). On Mondays, or when nobody has asked for a week, Home shows <b>Monday reorder round</b> with how many are waiting. The <b>repeat parts to ask about</b> tile on Home counts only the ones still to ask.'],
    ['Customers\' emails about orders and quotes?', 'Under the enquiries, <b>Customers writing about their orders</b> lists emails from customers about an order or a quote they already have. AI reads what each is about and shows it as a chip: <b>Complaint</b> (wrong, damaged, late or poor parts), <b>PO received</b> (a purchase order or go-ahead), <b>Question on a quote</b>, <b>Order change</b>, <b>Delivery</b>, <b>Lead time</b> (asking for sooner) or <b>Invoice</b>. Complaints and POs come first. When the email gives an order number (e.g. SO-9781) it shows beside the customer: press it to open the order. Each row has the buttons for what it is about: a complaint, <b>Make a task</b> (filled in as “Sort out SO-…: what they said”, due today) and <b>Open the order</b>; a PO, <b>Make the order</b>, or, when it is against one of our quotes, <b>Won quotes</b> (mark the quote as Ordered in the quote calculator first, then it is waiting there to become an order); a question on a quote, <b>Put on the chase list</b> (the question is noted on the quote, its follow-up is set to today, and the quote card in <b>Chase these today</b> shows <b>Customer asked</b> with the question); an order change, delivery or lead time, <b>Open the order</b> and <b>Draft a reply with AI</b> (it says it will be checked and you will come back to them, and never promises a date or a price); an invoice, the customer\'s <b>Orders and invoices</b>. Every row has <b>Open</b> (the email in Outlook) and <b>Done</b> (takes it off the list; Undo if not). <b>All done</b> clears the lot. A complaint, a PO and a question on a quote also come up in <b>Three things today</b> on Home. No prices are sent to the AI.'],
    ['Getting metal prices from several suppliers?', 'Sales orders › <b>Metal prices</b> (or <b>Ask for metal prices</b> on an order) › <b>Ask for prices</b>. Add a line for each metal: material, grade, form, thickness, size and quantity (or copy them from an earlier enquiry). Tick the suppliers to ask; add one from Xero and its email fills in. Press <b>Draft the emails</b>: each supplier gets the same enquiry, quoting the RFQ number, as a draft in your Outlook Drafts to check and send. When they reply, open the enquiry and press <b>Enter prices</b> for each: price per line, delivery charge and lead time. The cheapest is highlighted, with how much it saves, a warning when a price is up on the last time, and the last price paid on a Xero bill. Press <b>Order</b> on the one you choose: the purchase order form opens with that supplier, account 5000 and their prices, ready to send to Xero as a draft. <b>Price history</b> finds every price quoted here and every materials line on Xero bills in the last year: type e.g. <i>3mm 5083</i>.'],
    ['Notes for the shop floor?', 'Open a job (Jobs, Sales orders, or <b>Job details</b> on the shop floor) and use <b>Notes</b>: type a note and press <b>Post note</b>. It shows straight away on the shop floor card for that job (marked <b>New note</b>), as a yellow banner on the shop floor\'s station screen, and in the Notes column on the workshop TV (yellow until someone taps <b>Got it</b>). The shop floor answers on the same job: they type their name once on each tablet and press Reply. Their notes show on Levi\'s and Mandy\'s Home under <b>From the shop floor</b> until one of you taps <b>Got it</b> or replies. Each note says who wrote it and who has seen it. Levi and Mandy can remove a note. Never type prices in a note.'],
    ['Finding anything quickly (search)?', 'Type in the <b>Search</b> box in the top bar, on any screen (or press <b>/</b> to jump to it): an SO, PO, quote, delivery note or invoice number, a customer, a person\'s name, email or phone number, a part number or words from an order line, an enquiry or a task. Results come as you type, grouped; click one (or use the arrow keys and Enter) to open it. Spaces and dashes do not matter, so <b>so 9781</b> finds SO-9781. The shop floor login finds orders and delivery notes only, and prices are never searched. <b>CRM › Customers</b> with nobody picked shows who is worth a call, your tasks, who was active lately, and open orders with no contact saved.'],
    ['A customer\'s old files in SharePoint?', 'On a customer\'s page, the <b>Files</b> tab lists their client folder and their laser drawings (Bystronic) folder from the Company Data site, newest first, in groups: Drawings, Old quotes, Delivery notes, Certificates and Other. Search by file name (a part number is quickest); every file opens in SharePoint. The folder is found by the customer\'s name. Where the folder is named differently, press <b>Link a folder</b> (or <b>Change</b>), start typing its name and press <b>Link this folder</b>; <b>has none</b> stops a wrong one being offered. The board only reads these folders and never changes them; it keeps only which folder is whose. <b>Overview</b> also says how many old quotes they have had (from the QCLE numbers, including one-off quotes in MISCELLANEOUS named after them) and over which years, and Levi\'s <b>Think of ideas</b> is told this too. The shop floor does not see customer pages.'],
    ['Ideas: ideas for winning more work?', '<b>CRM › Ideas</b>. <b>Think of ideas</b>: AI reads what the board knows (what each customer buys and how often, who is growing or going quiet, repeat parts due, work they have never had from us, quotes, enquiries and any customer research) and suggests 6 to 8 ideas for the next fortnight, each saying why. <b>Write an email</b> drafts one with AI for you to check (it goes in your Outlook Drafts), <b>Make a task</b> puts it on Home, and mark each Doing it, Done or Not for us. <b>Customer research</b>: pick a customer (their website is guessed from their email addresses; change it if wrong) and press <b>Research</b>: AI reads their website, public LinkedIn and Facebook pages and recent news, then says what they do, what is new with them and where we could help, with links to where it read it. Check what it found before you use it. No prices are sent, nothing is posted, and about 10 to 20p a customer.'],
    ['Who sees prices?', 'Levi and Mandy see prices, purchase order costs, metal quotes, pro formas and the aged debt list; only Levi sees the month\'s figures (break-even and target), the CRM\'s totals and each customer\'s spend. The shop floor login (workshop@) sees customers, SO numbers, parts, quantities, due dates, processes, drawings, delivery notes and what is sent out, and never a price: the database refuses it, and so does the board\'s Xero connection. One thing to watch: the order\'s <b>Notes</b> and the notes on a job show on the shop floor and the TV, so never type a price there. Levi\'s quote lists in SharePoint (Factory Jobs) should stay closed to workshop@; the drawings library stays open so drawings show on the shop floor.'],
    ['Showing the board on the workshop TV?', 'On the TV\'s browser, sign in with the shop floor login, open the Shop floor and press <b>TV board</b>. It shows the whiteboard: every open job in the running order, a blue tick for each process done, an orange star for each still to do (filled in for the job\'s next step), <b>OUT</b> when it is at the powder coater, the due date (red when late) and a note (on hold, ready to dispatch, which company it is at). It shows every process on the order, even when the parts need different ones. It updates by itself and turns the page every 15 seconds when there are more jobs than fit. Nothing on it can be pressed. Press Esc (or go to the Shop floor) to leave it. Bookmark <i>jobs.clarke-lane.co.uk/#tv</i> to open it straight away. Each job has a small moving mark by its due date: a ticking stopwatch when late, an hourglass when due in the next few days, a cool face in sunglasses when on time, a lorry when ready to go and a sleepy zzz when on hold (the shop floor cards have them too). The top line has a mood for the day (Smooth sailing, or Pedal to the metal when jobs are late), and when a delivery note is made the TV shows <b>On its way!</b> for a few seconds. Screens set to reduce motion show the marks still. To leave the TV board, move the mouse or tap the screen and press <b>← Leave TV board</b> (top right), or press Esc.'],
    ['Sending work out for powder coating or plating?', 'On the Shop floor, the job card at P/Coat (or Plating) has <b>Send out</b>. Put in the company, what is going, the colour, the date it went and when it is due back (five working days unless you change it), then press <b>Sent out</b>. The <b>Sent out</b> tile on the Shop floor is the whiteboard: every job at each company, overdue ones in red, and jobs ready to go out. When it comes back press <b>Back in</b>: that ticks the process done (Undo puts it back). Levi and Mandy also see a Sent out card on Home and the send on the job\'s details.'],
    ['Emailing more than one person at a customer?', 'Put every address in the order\'s <b>Contact email</b> box with a comma (or semicolon) between them, e.g. <i>buyer@example.com, accounts@example.com</i>. The acknowledgement and pro forma drafts go to all of them, and delivery notes too unless the contact book has a goods-in person for that customer. To change them on an existing order, press <b>Amend order</b>.'],
    ['Keeping a copy of a delivery note?', 'Open the delivery note and press <b>Save PDF</b>. It saves to your Downloads named with the customer, the note number and the order, e.g. <i>Example Ltd - Delivery note - DN-0012 - SO-9781.pdf</i>. If you print and choose Save as PDF instead, it suggests the same name. Order acknowledgements and pro formas work the same way.'],
    ['Buying parts or outside work for an order (purchase order)?', 'Open the sales order and press New purchase order. Choose the supplier from Xero, add the lines (Copy this order\'s parts fills one line per part), put in the unit costs and press Create draft PO in Xero. It goes to Xero as a draft purchase order with the SO number as the reference; approve and send it from Xero. When the supplier\'s invoice comes in, Keith matches it to the PO in Xero. The PO is listed on the order with a link to it in Xero.'],
    ['Where do drawings go?', 'Open the order and press Attach drawings (PDFs and pictures show on the board; other files open in SharePoint). They are saved in SharePoint: Factory Jobs › Documents › Job drawings › the SO number. The shop floor sees a Drawing button on the job and it opens full screen. Remove only takes it off the job; the file stays in SharePoint.'],
    ['The customer must pay before we send (pro forma)?', 'Open the order and press New pro forma. Choose the quantities (everything still to send, or one call-off) and press Make the pro forma: it gets a PF number. Email it from there: the draft is copied to the accounts address (Keith) and asks the customer to quote the PF number when paying. When the money arrives press Mark paid; the order\'s draft invoices in Xero will then say Paid in advance with the PF number, so Keith can match the payment. A pro forma is not a VAT invoice and never goes to Xero itself. The first time, type the payment details and Keith\'s address in the box shown; they are kept for everyone in the office.'],
    ['Xero says its daily limit is used up?', 'Xero lets the board make 5,000 calls a day (and 60 a minute). Reading invoices, customers and products uses them up, so the board now reads Xero once and shares the answer with everyone on every computer: customers for 30 minutes, products for an hour, invoices for customer pages and Sales for 6 hours, unpaid invoices for 15 minutes. The <b>Xero</b> tab shows how many calls are left today. If the limit is used up, figures show as <i>Xero\'s figures from 14:05</i> until it frees up (Xero says when, usually within a few hours). Nothing is lost: dispatches waiting for Xero stay under <b>Dispatch › Waiting for Xero</b>; send them once it frees up, and each invoice still carries the dispatch date.'],
    ['The same order again?', 'Open the old one and press Repeat order. You get a new order with the same parts (part numbers and descriptions) and prices, new dates and a blank PO.'],
  );
  return `<section class="hsec" id="help-faq">${head(0, 'Questions')}<div class="hfaq">${q.map(([a, b]) => `<details class="hq"><summary>${a}</summary><p>${b}</p></details>`).join('')}</div>
    <p class="note">Anything else: contact Gecko IT.</p></section>`;
}

export function renderHelp(office) {
  const parts = office ? [video(), changeover(), home(true), newOrders(), orderForm(), orderExtras(), calloffs(), jobsBoard(), shopFloor(true), dispatch(true), mapAndCustomers(true), xero(), emails(true), faq(true)]
    : [home(false), shopFloor(false), dispatch(false), mapAndCustomers(false), faq(false)];
  const toc = office ? [['video', 'Watch the video'], ['changeover', 'Changeover day'], ['home', 'Home'], ['quotes', 'Won quotes', 1], ['form', 'Sales orders', 2], ['extras', 'Drawings, POs, pro forma'], ['calloffs', 'Call-offs', 3], ['jobs', 'Jobs', 4], ['floor', 'Shop floor', 5],
    ['dispatch', 'Dispatch', 6], ['xero', 'Xero', 7], ['map', 'Map'], ['customers', 'Customers'], ['email', 'Emails'], ['faq', 'Questions']]
    : [['home', 'Home'], ['floor', 'Shop floor'], ['dispatch', 'Dispatch'], ['map', 'Map'], ['faq', 'Questions']];
  return `<div class="sec-h"><h2>Help</h2><span class="sub">${office ? 'How an order goes from quote to invoice.' : 'How to use the shop floor screen.'} The pictures are examples, not real orders. Sign in at <b>jobs.clarke-lane.co.uk</b> with your Clarke Lane Microsoft account.</span></div>
    <div class="hlayout"><nav class="htoc" aria-label="Help sections">${toc.map(([k, t, no]) => `<a href="#help-${k}">${no ? `<small>${no}</small>` : '<small class="dot"></small>'}${t}</a>`).join('')}</nav>
    <div class="help">${flow(office)}${office ? '<a class="hcallout" href="#help-calloffs"><b>Most asked</b> How to set up and change call-offs <span aria-hidden="true">→</span></a>' : ''}${parts.join('')}</div></div>`;
}
